const PII: [string, string, string, boolean][] = [["key","[API_KEY]","\\b(?:sk-[A-Za-z0-9_-]{16,}|AKIA[0-9A-Z]{16}|ghp_[A-Za-z0-9]{30,}|AIza[0-9A-Za-z_-]{30,})\\b",false],["email","[EMAIL]","[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}",false],["ssn","[SSN]","\\b\\d{3}-\\d{2}-\\d{4}\\b",false],["card","[CARD]","\\b(?:\\d[ -]?){13,19}\\b",true],["phone","[PHONE]","(?<!\\d)(?:\\+?1[\\s.-]?)?\\(?\\d{3}\\)?[\\s.-]\\d{3}[\\s.-]\\d{4}(?!\\d)",false]];

function luhnOk(s: string): boolean {
  const d = s.replace(/\D/g, "");
  if (d.length < 13 || d.length > 19) return false;
  let sum = 0, alt = false;
  for (let i = d.length - 1; i >= 0; i--) { let n = Number(d[i]); if (alt) { n *= 2; if (n > 9) n -= 9; } sum += n; alt = !alt; }
  return sum % 10 === 0;
}

export function redactPII(text: string): { text: string; found: Record<string, number> } {
  const found: Record<string, number> = {};
  let out = String(text);
  for (const [kind, tag, src, luhn] of PII) {
    out = out.replace(new RegExp(src, "g"), (m) => {
      if (luhn && !luhnOk(m)) return m;
      found[kind] = (found[kind] || 0) + 1;
      return tag;
    });
  }
  return { text: out, found };
}

function hit(text: string, pat: string): boolean {
  const m = pat.match(/^\/(.+)\/([a-z]*)$/);
  if (m) { try { return new RegExp(m[1], m[2]).test(text); } catch { return false; } }
  return text.toLowerCase().includes(pat.toLowerCase());
}

export function validateOutput(text: string, rules: string): { ok: boolean; failed: string[] } {
  const t = String(text), failed: string[] = [];
  for (const rule of String(rules).split("\n").map((l) => l.trim()).filter((l) => l && !l.startsWith("#"))) {
    const mm = rule.match(/^max:\s*(\d+)$/i);
    if (mm) { if (t.length > Number(mm[1])) failed.push("is longer than " + mm[1] + " characters (" + t.length + ")"); }
    else if (/^json$/i.test(rule)) { try { JSON.parse(t.replace(/^```(?:json)?\s*|\s*```$/g, "")); } catch { failed.push("is not valid JSON"); } }
    else if (rule.startsWith("!")) { if (hit(t, rule.slice(1).trim())) failed.push("contains " + rule.slice(1).trim() + ", which is not allowed"); }
    else if (!hit(t, rule)) failed.push("is missing " + rule);
  }
  return { ok: failed.length === 0, failed };
}

export const CANARY = "CANARY-7391";
